import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {import('three/webgpu').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container for the card
  const root = new Group();

  // --------------------------------------------------------------------
  // Plane geometry & material (textured)
  // --------------------------------------------------------------------
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial();

  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously (function stays sync)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --------------------------------------------------------------------
  // Text content (headline)
  // --------------------------------------------------------------------
  const textItems =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: (config.colors?.paper ?? '#e8ecf2'),
      align: 'center',
    });

    // Position text slightly above the plane surface
    txt.position.set(0, 0.55, 0.01);
    root.add(txt);
  }

  // --------------------------------------------------------------------
  // Interaction handlers (hover rise‑in, click emit)
  // --------------------------------------------------------------------
  const originalY = plane.position.y;
  const hoverEnter = () => {
    gsap.to(plane.position, {
      y: originalY + 0.15,
      duration: 0.35,
      ease: 'power3.out',
    });
  };
  const hoverLeave = () => {
    gsap.to(plane.position, {
      y: originalY,
      duration: 0.35,
      ease: 'power3.out',
    });
  };
  const clickHandler = () => {
    ctx.emit('hub-journal.select');
  };

  // expose handlers for external event system
  root.userData.handlers = {
    hover: { enter: hoverEnter, leave: hoverLeave },
    click: clickHandler,
  };

  // --------------------------------------------------------------------
  // Cinematic primitives (if any)
  // --------------------------------------------------------------------
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handle = ctx.primitives[prim.name](root, prim.params);
      primitiveHandles.push(handle);
    }
  }

  // --------------------------------------------------------------------
  // Cleanup routine
  // --------------------------------------------------------------------
  root.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();

    // Kill any active GSAP tweens on the plane
    gsap.killTweensOf(plane.position);

    // Cleanup primitives
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') {
        h.cleanup();
      }
    }

    // Remove references
    root.traverse((obj) => {
      obj.userData = {};
    });
  };

  return root;
}
